protected static void parseInts(String str, int[] ints) {
        int len = str.length();
        int intIndex = 0;
        int currentInt = -1;
        ints[0] = -1;
        ints[1] = -1;
        ints[2] = -1;

        for (int i = 0; i < len; i++) {
            char c = str.charAt(i);
            if (c >= '0' && c <= '9') {
                if (currentInt == -1) {
                    currentInt = (c - '0');
                } else {
                    currentInt *= 10;
                    currentInt += (c - '0');
                }
            } else {
                if (currentInt >= 0) {
                    ints[intIndex++] = currentInt;
                    currentInt = -1;
                } else {
                    ints[intIndex++] = -1;
                }
            }
        }
        if (currentInt >= 0) {
            ints[intIndex] = currentInt;
        }
    }
